CREATE TABLE IF NOT EXISTS users (id BIGSERIAL PRIMARY KEY,full_name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,password_salt TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions (id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash TEXT NOT NULL UNIQUE,expires_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS books (id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,author TEXT NOT NULL,genre TEXT NOT NULL DEFAULT '',description TEXT NOT NULL DEFAULT '',cover_url TEXT NOT NULL DEFAULT '',total_pages INTEGER NOT NULL DEFAULT 1 CHECK(total_pages>0),current_page INTEGER NOT NULL DEFAULT 0 CHECK(current_page>=0),status TEXT NOT NULL DEFAULT 'want_to_read' CHECK(status IN ('want_to_read','reading','completed','abandoned')),favorite INTEGER NOT NULL DEFAULT 0 CHECK(favorite IN (0,1)),started_at DATE,finished_at DATE,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reading_sessions (id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,book_id BIGINT NOT NULL REFERENCES books(id) ON DELETE CASCADE,start_page INTEGER NOT NULL,end_page INTEGER NOT NULL,minutes INTEGER NOT NULL DEFAULT 0,read_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS journal_entries (id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,book_id BIGINT NOT NULL REFERENCES books(id) ON DELETE CASCADE,type TEXT NOT NULL CHECK(type IN ('note','quote')),content TEXT NOT NULL,page_number INTEGER,tags TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS goals (user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,daily_type TEXT NOT NULL DEFAULT 'pages' CHECK(daily_type IN ('pages','minutes')),daily_target INTEGER NOT NULL DEFAULT 30,annual_books INTEGER NOT NULL DEFAULT 12,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS email_verifications (email TEXT PRIMARY KEY,code_hash TEXT NOT NULL,token_hash TEXT,expires_at TIMESTAMPTZ NOT NULL,verified_at TIMESTAMPTZ,attempts INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reader_profiles (user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,favorite_genres TEXT NOT NULL DEFAULT '',onboarding_completed INTEGER NOT NULL DEFAULT 0,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_books_user ON books(user_id);
CREATE INDEX IF NOT EXISTS idx_sessions_user_date ON reading_sessions(user_id,read_at);
CREATE INDEX IF NOT EXISTS idx_journal_user ON journal_entries(user_id,created_at);
